const input = $input.first().json;
const d = input.body ?? input;
const n = (key) => d[key] === undefined || d[key] === null || d[key] === '' ? null : Number(d[key]);
const price = n('base_price');
const share = n('usd_cost_share');
const reference = n('reference_exchange_rate');
const current = n('current_exchange_rate');
const suppliedForecast = n('forecast_exchange_rate');
const errors = [];
if (!Number.isFinite(price) || price <= 0) errors.push('base_price debe ser mayor que cero.');
if (!Number.isFinite(share) || share < 0 || share > 1) errors.push('usd_cost_share debe estar entre 0 y 1.');
if (!Number.isFinite(reference) || reference <= 0) errors.push('reference_exchange_rate debe ser mayor que cero.');
if (!Number.isFinite(current) || current <= 0) errors.push('current_exchange_rate debe ser mayor que cero.');
if (d.forecast_exchange_rate !== undefined && d.forecast_exchange_rate !== null && d.forecast_exchange_rate !== '' && (!Number.isFinite(suppliedForecast) || suppliedForecast <= 0)) errors.push('forecast_exchange_rate debe ser mayor que cero.');
if (errors.length) return [{ json: { ok: false, statusCode: 400, errors } }];
const forecast = suppliedForecast ?? current;
const estimated = Math.round((price * ((1 - share) + share * forecast / reference) + Number.EPSILON) * 100) / 100;
const change = Math.round((estimated - price + Number.EPSILON) * 100) / 100;
return [{ json: { ok: true, product_id: d.product_id ?? null, base_price: price, usd_cost_share: share, reference_exchange_rate: reference, current_exchange_rate: current, forecast_exchange_rate: forecast, forecast_rate_source: suppliedForecast === null ? 'caller_current_rate' : 'caller_supplied_scenario', estimated_price: estimated, estimated_change: change, estimated_change_percent: Math.round(change / price * 10000) / 100, method: 'FX-weighted scenario: base price × ((1 - USD cost share) + USD cost share × forecast rate / reference rate)', disclaimer: 'Estimación de escenario basada en los datos recibidos; no es una predicción estadística ni una cotización oficial del BCB.' } }];
